    gl_FragColor.q = 1.;
#endif

#if defined(DEBUG_BITANGENTS)
    gl_FragColor.stp = normalize(P) * .5 + .5;
    gl_FragColor.q = 1.;
#endif
    if (uDebugReturn != 0.)
    {
        return;
    }
